<script>
(async()=>{"use strict";
const CORE=window.P2K_EVENTS_SHOWCASE_CORE,SITE=()=>window.P2K_SITE_CONFIG||{},esc=CORE?.escapeHTML||((v)=>String(v??""));
const arenasHost=document.querySelector("[data-arenas]"),dailyHost=document.querySelector("[data-daily]");let matches=[],filter="league",arenas=[],hydratedFilters=new Set(),logoPromises=new Map();
function initials(name){return(String(name||"?").trim().split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0]||"").join("")||"?").toUpperCase()}
function needClass(count){const n=Number(count);return !Number.isFinite(n)?"pc-gold":n<=0?"pc-green":n>=8?"pc-red":"pc-gold"}
function chooseFilter(rows){return rows.some(m=>m.joinable!==false&&m.category==="league")?"league":rows.some(m=>m.joinable!==false&&m.category==="friendly")?"friendly":"league"}
function visibleMatches(category=filter){return matches.filter(m=>m.joinable!==false&&m.category===category).slice(0,4)}
function logoKey(slug){return String(slug||"").trim().toLowerCase()}
async function fetchOpponentLogo(slug){const key=logoKey(slug),client=window.P2K_API_CLIENT;if(!key||!client?.json)return"";if(logoPromises.has(key))return logoPromises.get(key);const promise=client.json(`https://api.chess.com/pub/club/${encodeURIComponent(String(slug).trim())}`,{attempts:SITE().api?.defaultAttempts||3,priority:"foreground"}).then(club=>String(club?.icon||club?.image||"").trim()).catch(error=>{console.warn(`Events Showcase opponent logo ${key} unavailable.`,error);return""});logoPromises.set(key,promise);return promise}
async function hydrateMissingLogos(category){const targets=visibleMatches(category).filter(match=>!match.opponentLogo&&match.opponentSlug);if(!targets.length)return;await Promise.all(targets.map(async match=>{const logo=await fetchOpponentLogo(match.opponentSlug);if(!logo)return;const key=logoKey(match.opponentSlug);let changed=false;matches=matches.map(item=>{if(!item.opponentLogo&&logoKey(item.opponentSlug)===key){changed=true;return{...item,opponentLogo:logo}}return item});if(changed&&filter===category)renderDaily()}))}
function matchCard(match){const urgency=CORE.startUrgency(match.startTime),count=Number.isFinite(Number(match.recruitment?.count))?Number(match.recruitment.count):null,need=count===null?"Need ?":count===0?"Need ✓":`Need ${count}`,badge=match.category==="league"?((match.leagueAcronyms||[]).join("/")||"League"):"Friendly",opponent=match.opponentName||"Opponent",logo=match.opponentLogo?`<img class="pc-club-logo" src="${esc(match.opponentLogo)}" alt="${esc(opponent)} club logo" loading="lazy" referrerpolicy="no-referrer">`:`<div class="pc-logo-fallback" aria-hidden="true">${esc(initials(opponent))}</div>`,start=CORE.formatStartCompact(match.startTime),time=CORE.timePerMoveCompactLabel(match.timePerMove)||"—",timeFull=CORE.timePerMoveLabel(match.timePerMove)||"Time control unavailable",rating=match.ratingLabel||"Open",title=`${opponent} — ${match.name||`Match #${match.matchId}`} · ${urgency.title} · ${rating} · ${timeFull} · ${need}`,startMs=Number(match.startTime)*1000,league48=match.category==="league"&&Number.isFinite(startMs)&&startMs>=Date.now()&&startMs-Date.now()<=48*3600000,startClass=league48?"pc-red":urgency.level==="urgent"?"pc-red":urgency.level==="soon"?"pc-gold":"pc-muted";return`<a class="pc-card pc-match-card${league48?" pc-league-48h":""}" href="${esc(match.url)}" target="_blank" rel="noopener noreferrer" title="${esc(title)}" aria-label="${esc(title)}"><div class="pc-visual">${logo}<span class="pc-badge${match.category==="friendly"?" friendly":""}">${esc(badge)}</span>${match.urgent?'<span class="pc-priority" title="Priority">Priority</span>':""}</div><div class="pc-info"><div class="pc-line pc-primary"><span class="pc-match-start ${startClass}" title="${esc(urgency.title)}">${esc(start)}</span><span class="pc-match-separator">·</span><span class="pc-match-need ${needClass(count)}" title="Recruitment target: ${esc(need)}">${esc(need)}</span></div><div class="pc-line pc-secondary"><span class="pc-match-time" title="${esc(timeFull)}">${esc(time)}</span><span class="pc-match-separator">·</span><span class="pc-match-rating" title="Rating ${esc(rating)}">${esc(rating)}</span></div></div></a>`}
function renderDaily(){document.querySelectorAll("[data-filter]").forEach(b=>{const active=b.dataset.filter===filter;b.classList.toggle("is-active",active);b.setAttribute("aria-selected",active?"true":"false")});const visible=visibleMatches(filter);dailyHost.innerHTML=visible.map(matchCard).join("")||'<div class="pc-empty">No open priority match in this category.</div>'}
function arenaTiming(arena,now=Date.now()){const start=Date.parse(arena?.startAt||""),duration=Number(arena?.durationMinutes);if(!Number.isFinite(start)||!Number.isFinite(duration)||duration<=0)return null;const end=start+duration*60000;if(now>=end)return null;return{start,end,phase:now<start-3600000?"upcoming":now<start?"registration":"ongoing"}}
function parseArenaControl(value){const raw=String(value||"").trim().toLowerCase();if(!raw)return{kind:"rapid",label:"Rapid"};if(raw.includes("bullet"))return{kind:"bullet",label:"Bullet"};if(raw.includes("blitz"))return{kind:"blitz",label:"Blitz"};if(raw.includes("rapid"))return{kind:"rapid",label:"Rapid"};const hit=raw.match(/(\d+(?:\.\d+)?)\s*(?:\+|\||\/)\s*(\d+(?:\.\d+)?)/);const est=hit?Number(hit[1])+Number(hit[2])*40/60:Number(raw);if(Number.isFinite(est)&&est<3)return{kind:"bullet",label:"Bullet"};if(Number.isFinite(est)&&est<10)return{kind:"blitz",label:"Blitz"};return{kind:"rapid",label:"Rapid"}}
function speedIcon(kind){if(kind==="bullet")return'<svg class="pc-speed-icon bullet" viewBox="0 0 120 120" role="img" aria-label="Bullet"><path fill="currentColor" d="M20 72h52c18 0 30-10 30-24S90 24 72 24H59c-3 0-6 2-7 5L39 66c-1 4 2 6 6 6h27z"/><rect x="13" y="32" width="29" height="7" rx="3.5" fill="currentColor" opacity=".66"/><rect x="7" y="47" width="34" height="7" rx="3.5" fill="currentColor" opacity=".48"/><rect x="16" y="62" width="24" height="7" rx="3.5" fill="currentColor" opacity=".34"/></svg>';if(kind==="blitz")return'<svg class="pc-speed-icon blitz" viewBox="0 0 120 120" role="img" aria-label="Blitz"><path fill="currentColor" d="M68 8 24 66h29l-8 46 50-65H65z"/></svg>';return'<svg class="pc-speed-icon rapid" viewBox="0 0 120 120" role="img" aria-label="Rapid"><circle cx="60" cy="62" r="42" fill="none" stroke="currentColor" stroke-width="10"/><path d="M60 38v26l19 12" fill="none" stroke="currentColor" stroke-width="10" stroke-linecap="round" stroke-linejoin="round"/><path d="M42 12h36" stroke="currentColor" stroke-width="10" stroke-linecap="round"/></svg>'}
function formatCountdown(ms){const total=Math.max(0,Math.ceil(ms/1000)),h=Math.floor(total/3600),m=Math.floor((total%3600)/60),s=total%60;return`${h}h ${String(m).padStart(2,"0")}m ${String(s).padStart(2,"0")}s`}
function formatArenaStart(start){const date=new Date(start);if(!Number.isFinite(date.getTime()))return"—";const day=new Intl.DateTimeFormat("en-GB",{day:"numeric",month:"short"}).format(date),time=new Intl.DateTimeFormat("en-GB",{hour:"2-digit",minute:"2-digit",hour12:false}).format(date);return`${day} · ${time}`}
function formatStartsIn(ms){return`Starts in ${Math.max(1,Math.ceil(ms/60000))} mn`}
function arenaCard(arena,timing,now){const speed=parseArenaControl(arena.timeControl),status=timing.phase==="upcoming"?"Upcoming":timing.phase==="registration"?"Registration":"On-going",startText=formatArenaStart(timing.start),liveText=timing.phase==="ongoing"?formatCountdown(timing.end-now):timing.phase==="registration"?formatStartsIn(timing.start-now):startText,duration=arena.duration||"Duration —",control=arena.timeControl||"—",title=arena.name||"Arena";return`<a class="pc-card pc-arena-card" href="${esc(arena.link)}" target="_blank" rel="noopener noreferrer" title="${esc(title)}" aria-label="${esc(`${title} · ${status} · ${duration} · ${control} (${speed.label})`)}" data-arena-start="${timing.start}" data-arena-end="${timing.end}" data-arena-phase="${esc(timing.phase)}"><div class="pc-visual">${speedIcon(speed.kind)}<span class="pc-badge ${timing.phase}" data-arena-status>${esc(status)}</span></div><div class="pc-info"><div class="pc-arena-start-line ${timing.phase}" data-arena-live>${esc(liveText)}</div><div class="pc-arena-meta-line" title="Duration ${esc(duration)} · Time control ${esc(control)}"><strong>${esc(duration)}</strong> · ${esc(control)}</div></div></a>`}
function renderArenas(){const now=Date.now(),visible=arenas.map(a=>({a,t:arenaTiming(a,now)})).filter(x=>x.a?.active===true&&x.a?.name&&x.a?.link&&x.t).sort((a,b)=>a.t.start-b.t.start).slice(0,2);arenasHost.innerHTML=visible.map(x=>arenaCard(x.a,x.t,now)).join("")||'<div class="pc-empty">No active non-expired arena configured.</div>'}
function tickArenaClock(){const now=Date.now();let rerender=false;document.querySelectorAll(".pc-arena-card[data-arena-start]").forEach(card=>{const start=Number(card.dataset.arenaStart),end=Number(card.dataset.arenaEnd);if(!Number.isFinite(start)||!Number.isFinite(end)||now>=end){rerender=true;return}const phase=now<start-3600000?"upcoming":now<start?"registration":"ongoing";if(phase!==card.dataset.arenaPhase){rerender=true;return}if(phase==="upcoming")return;const live=card.querySelector("[data-arena-live]");if(!live)return;live.textContent=phase==="registration"?formatStartsIn(start-now):formatCountdown(end-now)});if(rerender)renderArenas()}
async function hydrateFilter(category){if(hydratedFilters.has(category))return;hydratedFilters.add(category);const targets=matches.filter(m=>m.category===category).slice(0,4);if(!targets.length)return;const applyUpdate=updated=>{const id=String(updated?.matchId||"");if(!id)return;matches=matches.map(m=>String(m.matchId)===id?updated:m);renderDaily()};const enriched=await CORE.enrichMatches(targets,{onUpdate:applyUpdate}),byId=new Map(enriched.map(m=>[String(m.matchId),m]));matches=matches.map(m=>byId.get(String(m.matchId))||m)}
async function selectFilter(category){filter=category;renderDaily();void hydrateMissingLogos(category);await hydrateFilter(category);renderDaily()}
async function load(){if(!CORE)throw Error("Events Showcase core unavailable.");const stateResponse=await fetch("api.php?action=state",{credentials:"same-origin",cache:"no-store"}),state=await stateResponse.json();if(!stateResponse.ok||state?.ok===false)throw Error(state?.error?.message||`HTTP ${stateResponse.status}`);arenas=Array.isArray(state.arenas)?state.arenas:[];renderArenas();hydratedFilters=new Set();const localCatalog=CORE.normalizeCatalog(state.catalog||[]),byId=new Map(localCatalog.map(m=>[String(m.matchId),m]));matches=(state.items||[]).filter(i=>i?.enabled!==false).map(i=>{const m=byId.get(String(i.matchId));return m?{...m,urgent:i?.urgent===true}:null}).filter(Boolean);filter=chooseFilter(matches);renderDaily();void hydrateMissingLogos(filter);await hydrateFilter(filter);let settled=chooseFilter(matches);if(settled!==filter){filter=settled;renderDaily();void hydrateMissingLogos(filter);await hydrateFilter(filter)}filter=chooseFilter(matches);renderDaily()}
document.querySelectorAll("[data-filter]").forEach(button=>button.addEventListener("click",()=>{void selectFilter(button.dataset.filter)}));
window.addEventListener("message",event=>{if(event.data?.type==="p2k-events-showcase-refresh")void load().catch(()=>{})});
window.setInterval(tickArenaClock,1000);
try{await load()}catch(error){console.error(error);dailyHost.innerHTML='<div class="pc-empty">Priority matches are temporarily unavailable.</div>';arenasHost.innerHTML='<div class="pc-empty">Arena data is temporarily unavailable.</div>'}
})();
